    public static string CreateRefreshPolicy(string requirementsJson, int maxSelectedRequests = 32) => Guard(() =>
    {
        var requirements = Requirements(Parse(requirementsJson)); if (maxSelectedRequests is < 0 or > 1000) throw Invalid();
        return new JsonObject { ["CriticalToolIds"] = new JsonArray(Arr(requirements["Tools"]).Select(t => (JsonNode?)Obj(t)["Id"]!.DeepClone()).ToArray()), ["MaxSelectedRequests"] = maxSelectedRequests, ["MaxIssuanceAttempts"] = 64, ["MaxTotalRequests"] = 768, ["MaxBootstrapRequests"] = 352, ["MaxInventoryRequests"] = 0, ["MaxInventoryPages"] = 0, ["MaxSourceRequests"] = 0, ["MaxSeconds"] = 900, ["MaxTransientRetries"] = 3, ["MaxUnresolvedAttempts"] = 3, ["PrivateMaxAgeHours"] = 24, ["ResearchMaxAgeHours"] = 168, ["FairnessPercent"] = 10 }.ToJsonString();
    });
    private static JsonObject RefreshPolicy(JsonObject p, JsonObject requirements)
    {
        Keys(p, "CriticalToolIds MaxSelectedRequests MaxIssuanceAttempts MaxTotalRequests MaxBootstrapRequests MaxInventoryRequests MaxInventoryPages MaxSourceRequests MaxSeconds MaxTransientRetries MaxUnresolvedAttempts PrivateMaxAgeHours ResearchMaxAgeHours FairnessPercent");
        var critical = Values(p["CriticalToolIds"]); if (critical.Length > 128 || critical.Distinct(StringComparer.Ordinal).Count() != critical.Length || critical.Any(id => !Arr(requirements["Tools"]).Select(Obj).Any(t => Text(t["Id"]) == id))) throw Invalid();
        foreach (string k in new[] { "MaxIssuanceAttempts", "MaxTotalRequests", "MaxBootstrapRequests", "MaxInventoryRequests", "MaxInventoryPages", "MaxSourceRequests" }) Range(p[k], 0, 1000000);
        Range(p["MaxSelectedRequests"], 0, 1000); Range(p["MaxSeconds"], 1, 3600); Range(p["MaxTransientRetries"], 0, 3); Range(p["MaxUnresolvedAttempts"], 1, 3); Range(p["PrivateMaxAgeHours"], 1, 24); Range(p["ResearchMaxAgeHours"], 1, 168); Range(p["FairnessPercent"], 0, 25); return p;
    }
    private static JsonObject RefreshPins(JsonObject p) { Keys(p, "SourceRevision PackageManifestSha256 SchemaSha256 CollectorSemanticsSha256 CatalogHash CohortHash LegacyInventoryHash"); Match(Text(p["SourceRevision"]), @"\A[a-f0-9]{40}\z", 40); foreach (var field in p.Where(f => f.Key != "SourceRevision")) Fingerprint(field.Value); return p; }
    private static JsonObject RefreshIdentity(JsonObject pins, JsonObject inventory, JsonObject context) { var identity = (JsonObject)pins.DeepClone(); identity["InventorySha256"] = Hash(inventory); identity["ComparisonContextSha256"] = Hash(context); return identity; }
    private static JsonObject RefreshApp(JsonObject app) { var r = new JsonObject(); foreach (string k in new[] { "AppId", "Registration", "Ownership", "AccountEnabled", "OwnerTenantId", "AssignmentRequired" }) r[k] = app[k]?.DeepClone(); return r; }
    private static JsonObject RefreshDescriptor(JsonObject profile, JsonObject tool, JsonObject client, JsonObject resource, string callback, string semantics, JsonObject inventory)
    {
        var c = RefreshApp(client); c["ChosenCallbackPresent"] = Values(client["RedirectUris"]).Contains(callback, StringComparer.Ordinal);
        var r = RefreshApp(resource); r["RequiredDefinitions"] = new JsonArray((resource["DelegatedScopeDefinitions"] as JsonArray ?? new JsonArray()).Select(Obj).Where(d => Values(tool["Scopes"]).Contains(Text(d["Value"]), StringComparer.Ordinal)).OrderBy(d => Text(d["Id"]), StringComparer.Ordinal).Select(d => (JsonNode?)new JsonObject { ["Id"] = d["Id"]!.DeepClone(), ["Value"] = d["Value"]!.DeepClone(), ["Enabled"] = d["Enabled"]?.DeepClone(), ["ConsentType"] = d["ConsentType"]?.DeepClone() }).ToArray());
        var applications = Arr(inventory["Applications"]).Select(Obj).ToArray(); var bootstrap = BootstrapRoute(profile, inventory, Date(inventory["CapturedAt"]));
        var bootstrapClient = applications.SingleOrDefault(a => Equal(a["AppId"], profile["BootstrapClientId"])); var bootstrapResource = applications.SingleOrDefault(a => Text(a["AppId"]) == Graph);
        var boot = new JsonObject { ["Client"] = bootstrapClient == null ? null : RefreshApp(bootstrapClient), ["Resource"] = bootstrapResource == null ? null : RefreshApp(bootstrapResource), ["CallbackUri"] = bootstrap?.RedirectUri, ["Definitions"] = bootstrapResource?["DelegatedScopeDefinitions"] is JsonArray bd ? new JsonArray(bd.Select(Obj).Where(d => Text(d["Value"]) == "User.Read").OrderBy(d => Text(d["Id"]), StringComparer.Ordinal).Select(d => (JsonNode?)new JsonObject { ["Id"] = d["Id"]!.DeepClone(), ["Value"] = d["Value"]!.DeepClone(), ["Enabled"] = d["Enabled"]?.DeepClone(), ["ConsentType"] = d["ConsentType"]?.DeepClone() }).ToArray()) : new JsonArray() };
        return new JsonObject { ["Bootstrap"] = boot, ["CompatibilityVersion"] = 1, ["Profile"] = profile.DeepClone(), ["Tool"] = tool.DeepClone(), ["Client"] = c, ["Resource"] = r, ["CallbackUri"] = callback, ["CollectorSemanticsSha256"] = semantics };
    }
    private static JsonObject ValidateRefreshDescriptor(JsonObject d)
    {
        Keys(d, "Bootstrap CompatibilityVersion Profile Tool Client Resource CallbackUri CollectorSemanticsSha256"); if (Int(d["CompatibilityVersion"]) != 1) throw Invalid(); var profile = Profile(Obj(d["Profile"])); var requirements = Header("TokenForgeToolRequirements"); requirements["Tools"] = new JsonArray(d["Tool"]!.DeepClone()); Requirements(requirements); Fingerprint(d["CollectorSemanticsSha256"]); var tool = Obj(d["Tool"]);
        foreach (string kind in new[] { "Client", "Resource" }) { var app = Obj(d[kind]); Keys(app, "AppId Registration Ownership AccountEnabled OwnerTenantId AssignmentRequired " + (kind == "Client" ? "ChosenCallbackPresent" : "RequiredDefinitions")); GuidId(app["AppId"]); Choice(app["Registration"], "Present Missing OwnerMismatch Unknown"); Choice(app["Ownership"], "Unverified PublishedMicrosoftOwner VerifiedMicrosoftOwner"); if (app["AccountEnabled"] != null) Bool(app["AccountEnabled"]); if (app["AssignmentRequired"] != null) Bool(app["AssignmentRequired"]); if (app["OwnerTenantId"] != null) GuidId(app["OwnerTenantId"]); if (kind == "Client") Bool(app["ChosenCallbackPresent"]); else { var definitions = Arr(app["RequiredDefinitions"]); if (definitions.Count > 64) throw Invalid(); var ids = new HashSet<string>(); foreach (var n in definitions) { var def = Obj(n); Keys(def, "Id Value Enabled ConsentType"); if (def["ConsentType"] != null) Choice(def["ConsentType"], "Admin User"); GuidId(def["Id"]); if (!ids.Add(Text(def["Id"])) || !Values(tool["Scopes"]).Contains(Text(def["Value"]), StringComparer.Ordinal)) throw Invalid(); if (def["Enabled"] != null) Bool(def["Enabled"]); } } }
        var boot = Obj(d["Bootstrap"]); Keys(boot, "Client Resource CallbackUri Definitions"); foreach (string kind in new[] { "Client", "Resource" }) if (boot[kind] != null) { var app = Obj(boot[kind]); Keys(app, "AppId Registration Ownership AccountEnabled OwnerTenantId AssignmentRequired"); GuidId(app["AppId"]); Choice(app["Registration"], "Present Missing OwnerMismatch Unknown"); Choice(app["Ownership"], "Unverified PublishedMicrosoftOwner VerifiedMicrosoftOwner"); foreach (string f in new[] { "AccountEnabled", "AssignmentRequired" }) if (app[f] != null) Bool(app[f]); if (app["OwnerTenantId"] != null) GuidId(app["OwnerTenantId"]); if (Text(app["AppId"]) != (kind == "Client" ? Text(profile["BootstrapClientId"]) : Graph)) throw Invalid(); }
        if (boot["CallbackUri"] != null && !Callback(Text(boot["CallbackUri"]), "Native")) throw Invalid(); if (Arr(boot["Definitions"]).Count > 64) throw Invalid(); foreach (var n in Arr(boot["Definitions"])) { var def = Obj(n); Keys(def, "Id Value Enabled ConsentType"); GuidId(def["Id"]); if (Text(def["Value"]) != "User.Read") throw Invalid(); if (def["Enabled"] != null) Bool(def["Enabled"]); if (def["ConsentType"] != null) Choice(def["ConsentType"], "Admin User"); }
        string client = Text(Obj(d["Client"])["AppId"]); if (!Values(profile["ApprovedClientIds"]).Contains(client, StringComparer.Ordinal) || !Values(tool["ClientIds"]).Contains(client, StringComparer.Ordinal) || !Equal(Obj(d["Resource"])["AppId"], tool["ResourceId"]) || Text(tool["Protocol"]) != "OAuth2V2Pkce" || !Callback(Text(d["CallbackUri"]), Text(tool["CallbackClass"]))) throw Invalid(); return d;
    }
    private static JsonObject RefreshContext(JsonObject d) => ContextFor(Obj(d["Profile"]), Obj(d["Tool"]), Text(Obj(d["Client"])["AppId"]), Text(d["CallbackUri"]));
    private static string RefreshFamily(JsonObject d) => Hash(new JsonObject { ["Tenant"] = Obj(d["Profile"])["ExpectedTenantFingerprint"]!.DeepClone(), ["Principal"] = Obj(d["Profile"])["ExpectedPrincipalFingerprint"]!.DeepClone(), ["ToolId"] = Obj(d["Tool"])["Id"]!.DeepClone(), ["ClientId"] = Obj(d["Client"])["AppId"]!.DeepClone(), ["ResourceId"] = Obj(d["Resource"])["AppId"]!.DeepClone() });
    private static string RefreshRequest(JsonObject d) { var context = RefreshContext(d); context.Remove("RecipeFingerprint"); context.Remove("ExecutionPolicyFingerprint"); return Hash(new JsonObject { ["FamilyId"] = RefreshFamily(d), ["Context"] = context }); }

    public static string PlanRefresh(string inputJson, DateTimeOffset? asOf = null) => Guard(() =>
    {
        var watch = Stopwatch.StartNew(); var input = Parse(inputJson); Keys(input, "Format SchemaVersion Profile Requirements Inventory Snapshot Pins Policy History"); Version(input, "TokenForgeRefreshInput"); var profile = Profile(Obj(input["Profile"])); var requirements = Requirements(Obj(input["Requirements"])); var inventory = Obj(input["Inventory"]); ChangeReports.Normalize("Inventory", inventory.ToJsonString()); var snapshot = Parse(ChangeReports.ValidateSnapshot(Obj(input["Snapshot"]).ToJsonString())); var pins = RefreshPins(Obj(input["Pins"])); var policy = RefreshPolicy(Obj(input["Policy"]), requirements); var now = asOf ?? DateTimeOffset.UtcNow; if (now > DateTimeOffset.UtcNow.AddMinutes(5)) throw Invalid();
        var evidence = RefreshEvidenceIndex(snapshot); var history = ValidateRefreshHistory(Obj(input["History"]), evidence); long validatedMs = watch.ElapsedMilliseconds;
        var apps = Arr(inventory["Applications"]).Select(Obj).ToDictionary(a => Text(a["AppId"]), StringComparer.Ordinal); bool inventoryFresh = Account(inventory, profile) && Fresh(inventory["CapturedAt"], now, Math.Min(Int(profile["MaxAgeHours"]), Int(policy["PrivateMaxAgeHours"])));
        var rows = new List<JsonObject>(); var exclusions = new JsonArray(); var allHistory = Arr(history["Entries"]).Select(Obj).ToArray();
        foreach (var tool in Arr(requirements["Tools"]).Select(Obj).OrderBy(t => Text(t["Id"]), StringComparer.Ordinal)) foreach (string clientId in Values(tool["ClientIds"]))
        {
            if (!Values(profile["ApprovedClientIds"]).Contains(clientId, StringComparer.Ordinal) || Text(tool["Protocol"]) != "OAuth2V2Pkce" || !apps.TryGetValue(clientId, out var client) || !apps.TryGetValue(Text(tool["ResourceId"]), out var resource))
            {
                exclusions.Add(new JsonObject { ["ToolId"] = tool["Id"]!.DeepClone(), ["ClientId"] = clientId, ["Reason"] = "NoApprovedImplementedRoute" }); continue;
            }
            var callbacks = Values(client["RedirectUris"]).Where(c => Callback(c, Text(tool["CallbackClass"]))).OrderBy(c => c, StringComparer.Ordinal).ToArray(); if (callbacks.Length > 8) { exclusions.Add(new JsonObject { ["ToolId"] = tool["Id"]!.DeepClone(), ["ClientId"] = clientId, ["Reason"] = "CallbackBoundExceeded" }); continue; }
            if (callbacks.Length == 0) { exclusions.Add(new JsonObject { ["ToolId"] = tool["Id"]!.DeepClone(), ["ClientId"] = clientId, ["Reason"] = "NoPublishedSupportedCallback" }); continue; }
            foreach (string callback in callbacks)
            {
                if (rows.Count >= 4096) throw Invalid(); var descriptor = RefreshDescriptor(profile, tool, client, resource, callback, Text(pins["CollectorSemanticsSha256"]), inventory); ValidateRefreshDescriptor(descriptor); string key = Hash(descriptor), family = RefreshFamily(descriptor), request = RefreshRequest(descriptor); var context = RefreshContext(descriptor); bool critical = Values(policy["CriticalToolIds"]).Contains(Text(tool["Id"]), StringComparer.Ordinal); int hours = critical ? Int(policy["PrivateMaxAgeHours"]) : Int(policy["ResearchMaxAgeHours"]);
                var matching = allHistory.Where(e => Text(e["RequestId"]) == request && Text(e["CompatibilityKey"]) == key).ToArray(); var attempts = matching.Select(e => RefreshHistoryState(e, evidence, now, hours)).OfType<JsonObject>().Where(s => Date(s["ObservedAt"]) <= now).OrderBy(s => Date(s["ObservedAt"])).ToArray(); var latest = matching.Length == 0 ? null : CombinedRefreshState(matching, evidence, now, hours); if (latest != null && Date(latest["ObservedAt"]) > now) latest = null; var success = attempts.LastOrDefault(s => Text(s["Outcome"]) == "Succeeded");
                // Unattached current observations can revoke reuse but cannot acquire a new compatibility identity.
                string currentDigest = Hash(snapshot); bool attached = matching.Any(e => Text(e["SnapshotSha256"]) == currentDigest);
                if (!attached) foreach (var collection in Arr(snapshot["Collections"]).Select(Obj).Where(c => Text(c["Privacy"]) == "Private" && (Text(c["EvidenceType"]) == "IssuedScopes" ? ExactContext(Obj(c["Context"]), context) : Text(c["EvidenceType"]) == "ApiAcceptance" && OperationContext(Obj(c["Context"]), context, profile, tool, "GraphMeV1"))))
                {
                    var dates = Arr(collection["Records"]).Select(Obj).Select(r => Date(r["ObservedAt"])).Append(Date(Obj(collection["Source"])["CollectedAt"])).Where(d => d <= now).ToArray(); if (dates.Length == 0) continue; var date = dates.Max(); if (latest == null || date >= Date(latest["ObservedAt"])) latest = new JsonObject { ["Outcome"] = "Unknown", ["ObservedAt"] = date.ToString("o"), ["Fresh"] = false, ["SnapshotSha256"] = currentDigest, ["ObservationReferences"] = new JsonArray() };
                }
                bool changed = allHistory.Any(e => Text(e["FamilyId"]) == family) && matching.Length == 0;
                int failures = 0; foreach (var state in attempts.Reverse()) { if (Text(state["Outcome"]) == "Succeeded") break; failures++; }
                string reason = changed && critical ? "ToolCriticalRelevantChange" : latest == null ? (critical ? "MissingEvidence" : "Exploration") : Text(latest["Outcome"]) != "Succeeded" ? "UnresolvedFailure" : Bool(latest["Fresh"]) ? "FreshEvidence" : "OverdueRefresh";
                int priority = reason switch { "ToolCriticalRelevantChange" => 0, "MissingEvidence" => 1, "UnresolvedFailure" => 2, "OverdueRefresh" => 3, "Exploration" => 4, _ => 5 }; DateTimeOffset? cooldown = latest != null && Text(latest["Outcome"]) == "StableFailure" ? Date(latest["ObservedAt"]).AddHours(Math.Min(168, 24 * Math.Pow(2, Math.Min(3, Math.Max(0, failures - 1))))) : null;
                string? defer = !inventoryFresh ? "PlanningInventoryNotCurrent" : !Eligible(client) || !Eligible(resource) ? "RouteNotVerifiedEnabled" : BootstrapRoute(profile, inventory, now) == null ? "NoSilentBootstrapRoute" : tool["Prerequisites"] is JsonArray prerequisites && prerequisites.Count > 0 ? "PrerequisiteObservationRequired" : reason == "FreshEvidence" ? "CompatibleFreshEvidence" : cooldown > now ? "StableFailureCooldown" : reason == "UnresolvedFailure" && latest != null && Text(latest["Outcome"]) != "StableFailure" && failures >= Int(policy["MaxUnresolvedAttempts"]) ? "UnresolvedAttemptLimit" : null;
                var reusable = reason == "FreshEvidence" ? matching.Single(e => Equal(e["SnapshotSha256"], latest!["SnapshotSha256"])) : null; var refs = reusable?["ObservationReferences"]?.DeepClone();
                rows.Add(new JsonObject { ["FamilyId"] = family, ["RequestId"] = request, ["CompatibilityKey"] = key, ["CompatibilityDescriptor"] = descriptor, ["Context"] = context, ["ExactIdentity"] = RefreshIdentity(pins, inventory, context), ["ToolId"] = tool["Id"]!.DeepClone(), ["Critical"] = critical, ["Reason"] = reason, ["Priority"] = priority, ["Selected"] = false, ["FairnessSelected"] = false, ["Deferral"] = defer, ["ObservedAt"] = latest?["ObservedAt"]?.DeepClone(), ["LastKnownSuccess"] = success?.DeepClone(), ["ReuseReferences"] = refs, ["ReuseOrigins"] = reason == "FreshEvidence" ? latest?["Origins"]?.DeepClone() : null, ["ReuseExactIdentity"] = reusable?["ExactIdentity"]?.DeepClone(), ["CooldownUntil"] = cooldown?.ToString("o"), ["FailureStreak"] = failures, ["RequiredIssuanceAttempts"] = 2, ["MaximumHttpRequests"] = 23 + Arr(tool["Operations"]).Count });
            }
