        var misses = new JsonArray(); if (!inventoryFresh) misses.Add(new JsonObject { ["Target"] = "PrivatePlanningInventory", ["Reason"] = "RequiresFreshSnapshotBeforeIssuance", ["MaxAgeHours"] = policy["PrivateMaxAgeHours"]!.DeepClone() }); foreach (var row in rows.Where(r => r["Deferral"] != null && Text(r["Deferral"]) != "CompatibleFreshEvidence")) misses.Add(new JsonObject { ["RequestId"] = row["RequestId"]!.DeepClone(), ["Reason"] = row["Deferral"]!.DeepClone() });
        var result = Header("TokenForgeRefreshPlan"); result["AsOf"] = now.ToString("o"); result["FrozenInput"] = input.DeepClone(); result["Policy"] = policy.DeepClone(); result["InputSha256"] = Hash(input); result["Pins"] = pins.DeepClone(); result["Candidates"] = new JsonArray(rows.OrderBy(r => Text(r["RequestId"]), StringComparer.Ordinal).Select(r => (JsonNode?)r).ToArray()); result["Excluded"] = exclusions; result["SelectedCount"] = selected.Count; result["ReusedCount"] = rows.Count(r => r["Deferral"]?.ToString() == "CompatibleFreshEvidence"); result["HasIssuancePlan"] = selected.Count > 0; result["FreshnessMisses"] = misses; result["AuthorizationEstablished"] = false; result["ExitCode"] = selected.Count > 0 || misses.Count > 0 || exclusions.Count > 0 ? 3 : 0; result["PlanId"] = Hash(result); result["Metrics"] = new JsonObject { ["ValidationMilliseconds"] = validatedMs, ["PlanningMilliseconds"] = watch.ElapsedMilliseconds - validatedMs, ["InputBytes"] = System.Text.Encoding.UTF8.GetByteCount(inputJson), ["ProcessStarts"] = 0, ["ExternalRequests"] = 0, ["DatabaseIoOperations"] = 0, ["CurrentProcessPeakWorkingSetBytes"] = Process.GetCurrentProcess().PeakWorkingSet64 }; return result.ToJsonString();
    });
